<?php
declare(strict_types=1);

/** Просмотр активных входов и завершение всех сессий, кроме текущей. */
require_once dirname(__DIR__) . '/include/app.php';app_require_admin();
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){app_require_csrf();app_require_admin_password();$current=app_admin_session_key();app_admin_sessions(static function(array &$state)use($current):void{foreach($state as $key=>&$item)if($key!==$current)$item['revoked']=true;});header('Location: /admin/sessions.php?revoked=1');exit;}
$current=app_admin_session_key();$sessions=app_admin_sessions(static fn(array &$state):array=>$state);
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Активные входы — Киосквода</title><link rel="stylesheet" href="/css/admin.css?v=20260816-7"></head><body><header class="admin-header"><div><strong>Киосквода</strong><span>Активные входы</span></div><nav><a href="/admin/">Панель владельца</a></nav></header><main class="admin-page"><div class="admin-page__heading"><div><p>Безопасность</p><h1>Активные входы</h1></div><span><?=count($sessions)?> сеансов</span></div><div class="session-list"><?php foreach($sessions as $key=>$item):?><article><div><strong><?=$key===$current?'Текущий вход':'Другое устройство'?></strong><span><?=app_h((string)$item['device'])?></span><small>IP: …<?=app_h((string)$item['ip_hash'])?> · активность <?=app_h(date('d.m.Y H:i',(int)$item['last_activity']))?></small></div><span class="<?=$item['revoked']?'unused-label':'ok-label'?>"><?=$item['revoked']?'Завершён':'Активен'?></span></article><?php endforeach;?></div><form class="confirm-bar" method="post"><input type="hidden" name="csrf" value="<?=app_h(app_csrf())?>"><label>Повторите пароль<input type="password" name="admin_password" required autocomplete="current-password"></label><button class="danger">Завершить остальные входы</button></form></main></body></html>
